// Build Date Window — Run once for all items: AN
const items = $input.all(); // alle eingehenden Items

function toEutilsDate(d) {
  return String(d || '2025-10-01').replaceAll('-', '/'); // YYYY/MM/DD
}

const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');

const maxdate = `${yyyy}/${mm}/${dd}`;
const today_sql = `${yyyy}-${mm}-${dd}`;

return items.map(({ json }) => {
  const { query_id, query, last_run } = json;
  return {
    json: {
      query_id,
      query,
      mindate: toEutilsDate(last_run),
      maxdate,
      datetype: 'edat',
      today_sql
    }
  };
});

const ids = ($input.item.json.esearchresult?.idlist || []).map(String);

// Kontext aus "Build Date Window" holen
const bw = $items('Function: Build Date Window', 0, 0)?.json;

const chunks = [];
for (let i = 0; i < ids.length; i += 200) {
  chunks.push({
    json: {
      id_chunk: ids.slice(i, i + 200).join(','),
      // Kontext beilegen:
      query_id: ($('MYSQL: Queries').first().json.query_id || 0),
      query: ($('MYSQL: Queries').first().json.query || ''),
      today_sql: ($('Function: Build Date Window').first().json.today_sql),
    }
  });
}
return chunks;

// ===== Utilities, die auch "_" (Text) aus XML-Node lesen =====
const mon = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,sept:9,oct:10,nov:11,dec:12};
const asArray = v => Array.isArray(v) ? v : (v == null ? [] : [v]);
const getText = v => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  if (typeof v === 'number') return String(v);
  if (typeof v === 'object') {
    // häufige Felder aus dem XML-Node
    return v._ ?? v['#text'] ?? v.__text ?? null;
  }
  return null;
};
const pad2 = n => String(n).padStart(2,'0');
const toInt = v => {
  const n = parseInt(getText(v) ?? v, 10);
  return Number.isNaN(n) ? null : n;
};

function normalizeDateYMD(y, m, d){
  const yy = toInt(y); if (!yy) return null;
  let mm = getText(m) ?? m;
  if (typeof mm === 'string' && isNaN(mm)) {
    const key3 = mm.slice(0,3).toLowerCase();
    const key4 = mm.slice(0,4).toLowerCase();
    mm = mon[key4] ?? mon[key3];
  }
  mm = toInt(mm) || 1;
  const dd = toInt(d) || 1;
  if (mm < 1 || mm > 12 || dd < 1 || dd > 31) return null;
  const dt = new Date(Date.UTC(yy, mm-1, dd));
  if (dt.getUTCFullYear()!==yy || dt.getUTCMonth()+1!==mm || dt.getUTCDate()!==dd) return null;
  return `${String(yy).padStart(4,'0')}-${pad2(mm)}-${pad2(dd)}`;
}

function extractPublishedDate(article, pubmedData){
  const pd = article?.Journal?.JournalIssue?.PubDate || {};
  let norm = normalizeDateYMD(pd?.Year, pd?.Month, pd?.Day);
  if (norm) return norm;

  for (const ad of asArray(article?.ArticleDate)){
    norm = normalizeDateYMD(ad?.Year, ad?.Month, ad?.Day);
    if (norm) return norm;
  }

  for (const h of asArray(pubmedData?.History?.PubMedPubDate)){
    norm = normalizeDateYMD(h?.Year, h?.Month, h?.Day);
    if (norm) return norm;
  }

  if (pd?.Year) return `${String(getText(pd.Year)).padStart(4,'0')}-01-01`;
  return null;
}

function extractAuthors(authorList){
  const authors = [];
  for (const a of asArray(authorList?.Author)){
    const last = getText(a?.LastName) || '';
    const fore = getText(a?.Initials) || '';
    const full = (last && fore) ? `${last} ${fore}` : (last || fore);
    if (full) authors.push(full);
  }
  return authors.join(', ') || null;
}

function extractAbstract(article){
  const raw = article?.Abstract?.AbstractText;
  if (!raw) return null;
  const parts = [];
  for (const seg of asArray(raw)){
    if (typeof seg === 'string') {
      if (seg.trim()) parts.push(seg.trim());
    } else {
      const label = seg?.Label || seg?.['@_Label'];
      const txt = (getText(seg) || '').trim();
      if (txt) parts.push(label ? `${label}: ${txt}` : txt);
    }
  }
  const joined = parts.join('\n\n').trim();
  return joined || null;
}

function extractIds(articleIdList){
  const out = { doi:null, pmcid:null, pii:null };
  for (const id of asArray(articleIdList?.ArticleId)){
    const t = id?.IdType || id?.['@_IdType'];
    const v = getText(id);
    if (!t || !v) continue;
    const tt = String(t).toLowerCase();
    if (tt === 'doi') out.doi = v;
    else if (tt === 'pmc') out.pmcid = v;
    else if (tt === 'pii') out.pii = v;
  }
  return out;
}

function extractPages(article){
  const pg = article?.Pagination;
  if (!pg) return null;
  return getText(pg.MedlinePgn) || getText(pg.StartPage) || null;
}

function extractPubTypes(ptList){
  const arr = asArray(ptList?.PublicationType);
  const vals = arr.map(getText).filter(Boolean);
  return vals.length ? vals.join(', ') : null;
}

function extractMesh(meshList){
  const out = [];
  for (const mh of asArray(meshList?.MeshHeading)){
    const d = getText(mh?.DescriptorName);
    const q = asArray(mh?.QualifierName).map(getText).filter(Boolean);
    if (d) out.push(q.length ? `${d} (${q.join('; ')})` : d);
  }
  return out.length ? out.join(' | ') : null;
