function strip4Byte(s) {
  if (!s) return s;
  // 4-Byte entfernen (Emojis etc.)
  s = s.replace(/[\u{10000}-\u{10FFFF}]/gu, '')
  .replace(/[„“"]/g, '"')
  .replace(/[‚‘’]/g, "'")
  .replace(/[–—]/g, '-')
  .replace(/\u00A0/g, ' ')
  .replace(/…/g, '...')
  .replace(/β/g, 'beta')
  .replace(/α/g, 'alpha');
  // optional: Unicode-Normalisierung (NFC), falls Node-Version es kann
  if (typeof s.normalize === 'function') s = s.normalize('NFC');
  return s;
}

const json = $('Loop Over Items').first().json;

const titel = strip4Byte(json.PubmedResultTitel);
const autoren = strip4Byte(json.PubmedResultAutoren)
const jahr = (json.PubmedResultPublishedDate).substring(0,4);
const volume = json.PubmedResultVolume ? json.PubmedResultVolume : '';
const pages = json.PubmedResultPages ? json.PubmedResultPages : '';
const journal = strip4Byte(json.PubmedResultJournal);
const pmid = json.PubmedResultPMID;
const inseriert = json.PubmedResultInseriert;
const pmcid = json.PubmedResultPMCID ? 'https://www.ncbi.nlm.nih.gov/pmc/articles/' + json.PubmedResultPMCID : '';
const abstract = strip4Byte(json.PubmedResultAbstract);
const abstractdeutsch = strip4Byte(json.PubmedResultAbstractDeutsch);
const zusammenfassung = strip4Byte(json.PubmedResultZusammenfassung);
const keywords = strip4Byte(json.PubmedResultKeywords);

return {
  titel: titel,
  autoren: autoren,
  jahr: jahr,
  volume: volume,
  pages: pages,
  journal: journal,
  pmid: pmid,
  inseriert: inseriert,
  pmcid: pmcid,
  abstract: abstract,
  abstractdeutsch: abstractdeutsch,
  zusammenfassung: zusammenfassung,
  keywords: keywords
};

