return items.map(item => {
  // Ollama /api/chat liefert den eigentlichen strukturierten Inhalt
  // als JSON-String in message.content.
  const raw =
    item.json?.message?.content ??
    item.json?.response ??
    item.json;

  let data;

  if (typeof raw === 'string') {
    try {
      data = JSON.parse(raw);
    } catch (error) {
      throw new Error(
        `Ollama message.content enthält kein valides JSON: ${error.message}\n\n` +
        `Antwortanfang: ${raw.slice(0, 500)}`
      );
    }
  } else {
    data = raw;
  }

  // Minimale Plausibilitätsprüfung
  if (
    !data ||
    typeof data !== 'object' ||
    !Array.isArray(data.erkenntnisse) ||
    !Array.isArray(data.zusammenfassung) ||
    !Array.isArray(data.produkte) ||
    !Array.isArray(data.organisationen) ||
    !Array.isArray(data.offene_fragen)
  ) {
    throw new Error(
      'Ollama-Antwort entspricht nicht dem erwarteten Scientific-Intelligence-Schema.'
    );
  }

  const lines = [];

  // ---------------------------------------------------------
  // Relevante Erkenntnisse
  // ---------------------------------------------------------

  lines.push('# Relevante Erkenntnisse');
  lines.push('');

  if (data.erkenntnisse.length > 0) {
    for (const e of data.erkenntnisse) {
      lines.push(`## ${e.klasse} – ${e.thema}`);
      lines.push('');
      lines.push(`- **Aussage:** ${e.aussage}`);
      lines.push(`- **Evidenz:** ${e.evidenz}`);
      lines.push(
        `- **Strategische Relevanz:** ${e.strategische_relevanz}`
      );
      lines.push(
        `- **EUROIMMUN erwähnt:** ${
          e.euroimmun_erwaehnt ? 'Ja' : 'Nein'
        }`
      );
      lines.push('');
    }
  } else {
    lines.push('Nicht erwähnt');
    lines.push('');
  }

  // ---------------------------------------------------------
  // Zusammenfassung
  // ---------------------------------------------------------

  lines.push('# Zusammenfassung');
  lines.push('');

  if (data.zusammenfassung.length > 0) {
    lines.push(data.zusammenfassung.join(' '));
  } else {
    lines.push('Nicht erwähnt');
  }

  lines.push('');

  // ---------------------------------------------------------
  // Produkte
  // ---------------------------------------------------------

  lines.push('# Erwähnte Produkte');
  lines.push('');

  if (data.produkte.length > 0) {
    for (const p of data.produkte) {
      lines.push(`- **${p.name}**`);
      lines.push(`  - Typ: ${p.typ}`);
      lines.push(
        `  - Hersteller: ${p.hersteller || 'Nicht erwähnt'}`
      );
      lines.push(`  - Verwendung: ${p.verwendung}`);
      lines.push(
        `  - EUROIMMUN-Bezug: ${
          p.euroimmun_bezug ? 'Ja' : 'Nein'
        }`
      );
    }
  } else {
    lines.push('Nicht erwähnt');
  }

  lines.push('');

  // ---------------------------------------------------------
  // Organisationen
  // ---------------------------------------------------------

  lines.push('# Erwähnte Organisationen');
  lines.push('');

  if (data.organisationen.length > 0) {
    for (const o of data.organisationen) {
      lines.push(`- **${o.name}**`);
      lines.push(`  - Typ: ${o.typ}`);
      lines.push(`  - Rolle: ${o.rolle}`);
    }
  } else {
    lines.push('Nicht erwähnt');
  }

  lines.push('');

  // ---------------------------------------------------------
  // Offene Fragen
  // ---------------------------------------------------------

  lines.push('# Offene Fragen');
  lines.push('');

  if (data.offene_fragen.length > 0) {
    for (const frage of data.offene_fragen) {
      lines.push(`- ${frage}`);
    }
  } else {
    lines.push('Nicht erwähnt');
  }

  // ---------------------------------------------------------
  // Sauberer Output
  // ---------------------------------------------------------

  return {
    json: {
      ScientificIntelligence: data,

      ScientificIntelligenceMarkdown: lines.join('\n'),

      ScientificIntelligenceMeta: {
        model: item.json.model ?? 'unsloth-qwen3.5:9b',
        schemaVersion: '1.0',
        generatedAt: new Date().toISOString(),

        ollama: {
          createdAt: item.json.created_at ?? null,
          doneReason: item.json.done_reason ?? null,
          promptTokens: item.json.prompt_eval_count ?? null,
          outputTokens: item.json.eval_count ?? null,
          totalDurationNs: item.json.total_duration ?? null
        }
      }
    }
  };
});

